import json, pathlib, html
p=pathlib.Path(__file__).parent
m=json.loads((p/'manifest.json').read_text(encoding='utf-8-sig'))
names={'Blaster':'Alien blaster','MurderSword':'Murderer sword','SheriffHammer':'Sheriff revolver','DualRifle':'Shotgun / rifle','BoxingGlove':'Giant boxing glove','RocketLauncher':'RPG rocket launcher','DualUzi':'Dual alien spike Uzis','ChainGun':'Chain gun','GrenadeLauncher':'Electric grenade launcher','WristLaser':'Wrist laser','NeedleDrill':'Needle drill','StockPistol':'Stock pistol','SawStaff':'Saw wheel staff','BarbedBat':'Barbed baseball bat','Chainsaw':'Chainsaw launcher','LaserClaws':'Laser claws','FlamingMarshmallow':'Flaming marshmallow','LaserAxe':'Laser axe','Dagger':'Dagger'}
m['names']=names
page=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deadly Jenga · Weapon showcase</title><style>
:root{color-scheme:dark;font-family:Inter,Segoe UI,system-ui,sans-serif;background:#10101b;color:#f4f3fc}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button,select,.download{cursor:pointer;border:1px solid #48415e;background:#272135;color:inherit;border-radius:10px;padding:10px 14px}button:hover,button.active{background:#7050a8;border-color:#b492ff}header{padding:32px 36px 20px;background:linear-gradient(110deg,#31204d,#112f3b)}h1{font-size:32px;letter-spacing:-1px;margin:8px 0}p{color:#c9c4d9;line-height:1.6;max-width:950px;margin:8px 0}.eyebrow{color:#74f4c6;font-size:12px;letter-spacing:3px;font-weight:700}.layout{display:grid;grid-template-columns:240px 1fr;min-height:75vh}aside{background:#181522;padding:20px 14px;position:sticky;top:0;align-self:start;height:100vh;overflow:auto}aside button{display:block;width:100%;text-align:left;margin:5px 0;font-size:14px;padding:10px}input{width:100%;background:#0d0c15;border:1px solid #48415e;color:white;border-radius:9px;padding:11px;margin-bottom:12px}main{padding:26px 32px;min-width:0}h2{font-size:28px;margin:0 0 8px}.controls{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin:18px 0 24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}.shot{padding:0;overflow:hidden;text-align:left;background:#1d192a;border:1px solid #393246;border-radius:13px}.shot img{width:100%;aspect-ratio:4/3;object-fit:contain;display:block;background:#111}.caption{display:flex;justify-content:space-between;padding:13px 15px;font-size:14px}.tag{color:#b6a2d8;font-size:12px}.note{font-size:13px;color:#aaa2b8}.download{display:inline-block;text-decoration:none;font-size:13px;margin:14px 10px 0 0}.dialog{position:fixed;inset:0;background:#08080ef5;z-index:20;display:none;grid-template-rows:auto 1fr auto;padding:14px}.dialog.open{display:grid}.bar{display:flex;justify-content:space-between;align-items:center;gap:12px}.large{width:100%;height:100%;min-height:0;object-fit:contain}.bottom{justify-content:center;padding:10px}a{color:#84f4d2}.hidden{display:none}@media(max-width:750px){.layout{grid-template-columns:1fr}aside{position:relative;height:auto;max-height:240px}main,header{padding:20px}.grid{grid-template-columns:1fr}h1{font-size:26px}}
.overview-grid{grid-template-columns:repeat(auto-fit,minmax(min(100%,450px),1fr))}.overview-pair{display:grid;grid-template-columns:1fr 1fr;gap:2px}.pair-label{display:block;padding:8px 12px;color:#b8b0c8;font-size:12px}</style><header><div class="eyebrow">DEADLY JENGA · ACTUAL UNITY CAPTURES</div><h1>The current arsenal, from every side.</h1><p>Inspect each weapon alone, held by the production player avatar, and stowed. These are the current game models rendered in the Game scene’s lighting and sky, with staged poses. No concept art or replacement models.</p><p class="note" id="stats"></p><a class="download" href="WeaponShowcase.zip">Download all images + gallery</a></header><div class="layout"><aside><input id="search" placeholder="Find a weapon…" aria-label="Find a weapon"><nav id="nav"></nav></aside><main><h2 id="title"></h2><p class="note" id="details"></p><div class="controls"><select id="mode" aria-label="Weapon mode"></select><div id="filters"></div></div><div class="grid" id="grid"></div><p class="note">Click a photo to enlarge. Use ← / → to browse, Esc to close. Camera angles are labelled relative to the weapon/player; all images are 1600 × 1200. This gallery shows appearance, not firing effects or headset verification.</p></main></div><div class="dialog" id="lightbox" role="dialog" aria-modal="true" aria-label="Weapon photo"><div class="bar"><span id="label"></span><button id="close">Close ×</button></div><img class="large" id="large"><div class="bar bottom"><button id="prev">← Previous</button><a id="original" target="_blank">Open original</a><a id="save" download>Download</a><button id="next">Next →</button></div></div><script>const data=__DATA__;
const $=s=>document.querySelector(s),names=data.names,keys=[...new Set(data.shots.map(s=>s.weapon))];let chosen=null,filter='All',shown=[],current=0;
const modeNames={DualRifle:['Rifle','Shotgun'],SheriffHammer:['Revolver','Alternate / shotgun'],StockPistol:['Full auto','Burst'],Chainsaw:['Cutting','Wheel launcher'],LaserAxe:['Axe','Laser']};
function modeLabel(s){return (modeNames[s.weapon]||['Primary','Alternate'])[s.mode==='Alternate'?1:0]||s.mode}
function viewLabel(s){let n=Number(s.view.slice(-1));return s.view.startsWith('Weapon')?['','Three-quarter front','Opposite side','Three-quarter rear'][n]:s.view.startsWith('Held')?['','Held · front','Held · side','Held · rear'][n]:'Holstered · rear'}
function nav(){let q=$('#search').value.toLowerCase();$('#nav').innerHTML='<button data-key="" class="'+(!chosen?'active':'')+'">Arsenal overview</button>'+keys.filter(k=>(names[k]||k).toLowerCase().includes(q)).map(k=>`<button data-key="${k}" class="${k===chosen?'active':''}">${names[k]||k}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{chosen=b.dataset.key||null;setup()})}
function setup(){nav();if(!chosen){$('#mode').parentElement.classList.add('hidden');overview();return;}$('#mode').parentElement.classList.remove('hidden');$('#grid').classList.remove('overview-grid');$('#title').textContent=names[chosen]||chosen;let modes=[...new Set(data.shots.filter(s=>s.weapon===chosen).map(s=>s.mode))];$('#mode').innerHTML=modes.map(m=>`<option value="${m}">${modeLabel({weapon:chosen,mode:m})}</option>`).join('');$('#mode').classList.toggle('hidden',modes.length<2);$('#details').textContent=chosen==='WristLaser'?'The wrist cuff remains attached when stowed.':chosen==='DualUzi'||chosen==='LaserClaws'?'Paired weapon: both hands use the production paired models.':'Production mesh, materials and attachment placement. Select an alternate mode where available.';render()}
function overview(){
$('#title').textContent='Arsenal overview';$('#details').textContent='Compare the weapon model and its scale on the player. Choose a card for every angle, alternate mode and stowed view.';$('#grid').classList.add('overview-grid');shown=[];
let q=$('#search').value.toLowerCase();$('#grid').innerHTML=keys.filter(k=>(names[k]||k).toLowerCase().includes(q)).map(k=>{let a=data.shots.find(s=>s.weapon===k&&s.view==='Weapon 1'),b=data.shots.find(s=>s.weapon===k&&s.view==='Held 1'),count=data.shots.filter(s=>s.weapon===k).length;return `<button class="shot" data-open="${k}"><div class="overview-pair"><div><img src="${a.file}" loading="lazy" alt="${names[k]} weapon model"><span class="pair-label">Weapon model</span></div><div><img src="${b.file}" loading="lazy" alt="${names[k]} held by player"><span class="pair-label">Player holding</span></div></div><div class="caption"><span>${names[k]||k}</span><span class="tag">${count} photos →</span></div></button>`}).join('');$('#grid').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{chosen=b.dataset.open;setup();window.scrollTo({top:0,behavior:'smooth'})});
}
function render(){$('#filters').innerHTML=['All','Weapon only','Player holding','Holstered'].map(f=>`<button data-filter="${f}" class="${f===filter?'active':''}" style="margin-right:6px">${f}</button>`).join('');$('#filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});shown=data.shots.filter(s=>s.weapon===chosen&&s.mode===$('#mode').value&&(filter==='All'||filter==='Weapon only'&&s.view.startsWith('Weapon')||filter==='Player holding'&&s.view.startsWith('Held')||filter==='Holstered'&&s.view==='Holstered'));$('#grid').innerHTML=shown.map((s,i)=>`<button class="shot" data-i="${i}"><img src="${s.file}" loading="lazy" alt="${names[s.weapon]} — ${viewLabel(s)}"><div class="caption"><span>${viewLabel(s)}</span><span class="tag">${modeLabel(s)}</span></div></button>`).join('');$('#grid').querySelectorAll('button').forEach(b=>b.onclick=()=>open(Number(b.dataset.i)))}
function open(i){current=(i+shown.length)%shown.length;let s=shown[current];$('#large').src=s.file;$('#large').alt=names[s.weapon]+' '+viewLabel(s);$('#label').textContent=`${names[s.weapon]} · ${modeLabel(s)} · ${viewLabel(s)} (${current+1}/${shown.length})`;$('#original').href=$('#save').href=s.file;$('#lightbox').classList.add('open')}
$('#close').onclick=()=>$('#lightbox').classList.remove('open');$('#prev').onclick=()=>open(current-1);$('#next').onclick=()=>open(current+1);document.onkeydown=e=>{if(!$('#lightbox').classList.contains('open'))return;if(e.key==='Escape')$('#close').click();if(e.key==='ArrowLeft')open(current-1);if(e.key==='ArrowRight')open(current+1)};$('#mode').onchange=render;$('#search').oninput=()=>{nav();if(!chosen)overview()};$('#stats').textContent=`${keys.length} weapons · ${data.shots.length} photographs · captured ${data.captured.slice(0,10)} · production Game scene`;setup();</script></html>'''
(p/'index.html').write_text(page.replace('__DATA__',json.dumps(m)),encoding='utf-8')
print(f'Gallery: {len(names)} labels, {len(m["shots"])} photos')
